/* 各课零基础互动小课：先让学习者看懂变量，再进入原有正文。 */
(()=>{
  const esc=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const wrap=(id,title,why,body)=>'<section class="beginner-workshop" data-bw-root="'+id+'" aria-labelledby="bw-title-'+id+'"><div class="bw-heading"><span class="chapter-kicker">先看懂一个具体例子</span><h2 id="bw-title-'+id+'">'+title+'</h2><p>'+why+'</p></div>'+body+'</section>';
  const demos={
    'ai-foundations':()=>wrap('ai-foundations','先看清：输入、计算、答案和学习分别是什么','用“这张照片里有没有猫？”贯穿 AI 入门。模型先接收数字，再按参数计算；训练用标准答案调整参数，推理用学好的参数处理新照片。','<div class="bw-ai-flow"><div><b>输入</b><span>一张照片</span><small>像素数字</small></div><i aria-hidden="true">→</i><div><b>模型</b><span>按参数计算</span><small>权重与偏置</small></div><i aria-hidden="true">→</i><div><b>输出</b><span>有猫原始分数 z=1.5</span><small>还不是概率</small></div><i aria-hidden="true">→</i><div><b>对答案</b><span>真实：有猫</span><small>训练时用来改参数</small></div></div><div class="bw-layout-compare"><div><strong>训练 Training</strong><p>给许多带答案的例子，比较预测和标签，再调整参数。</p></div><div><strong>推理 Inference</strong><p>拿学到的参数处理新输入，输出预测；通常不更新参数。</p></div></div><p class="bw-note">AI 是希望机器完成智能任务的大范围目标；机器学习是从数据中学习规律的一类方法；深度学习使用多层神经网络。三者相关，但不是同义词。</p>'),
    tensor:()=>wrap('tensor','数字怎样变成有形状的数据？','先从最熟悉的数字开始。形状只数每一组有多少个数；轴名再告诉我们每个方向代表什么。','<div class="bw-shape-choices" role="group" aria-label="选择一种数组形状"><button type="button" data-bw-shape="scalar" aria-pressed="true">一个数</button><button type="button" data-bw-shape="row" aria-pressed="false">一排数</button><button type="button" data-bw-shape="table" aria-pressed="false">数字表</button><button type="button" data-bw-shape="image" aria-pressed="false">一张彩色小图</button></div><div class="bw-shape-demo"><div class="bw-shape-grid" data-bw-shape-grid></div><p data-bw-shape-readout role="status"></p></div><p class="bw-note">换形状只改变数字的分组方式，不会凭空增加或减少数字；同一组数字的顺序也不会自动变成别的意思。</p>'),
    network:()=>wrap('network','一个神经元怎样完成乘加？','用一个输入 x、一个权重 w 和一个偏置 b 做乘加。先观察输入、权重和偏置怎样改变乘加结果 z；本课只需读懂这一步。','<div class="bw-network-controls"><label>x 输入 <output data-bw-net-x-out>2.0</output><input type="range" min="0" max="4" step="0.1" value="2" data-bw-net-x aria-label="调整输入 x"></label><label>w 权重 <output data-bw-net-w-out>1.5</output><input type="range" min="0" max="3" step="0.1" value="1.5" data-bw-net-w aria-label="调整权重 w"></label><label>b 偏置 <output data-bw-net-b-out>−1.0</output><input type="range" min="-2" max="2" step="0.1" value="-1" data-bw-net-b aria-label="调整偏置 b"></label></div><div class="bw-readouts"><div><small>乘加输出 z</small><strong data-bw-net-z>2.00</strong><code>z = w×x + b</code></div></div><details class="depth-advanced"><summary>选学：把分数用于二分类时，怎样转成概率</summary><p>若把 z 用作二分类的原始分数（logit），Sigmoid 可将它转换为正类概率。后面的概率课程会逐步解释；暂时可以先跳过。</p><div class="bw-readouts"><div><small>经过 Sigmoid 的概率</small><strong data-bw-net-p>0.881</strong><span class="bw-equation">\\(p=\\frac{1}{1+e^{-z}}\\)</span></div></div></details><p class="bw-note">z 是本例的一次乘加结果，可以小于 0，也可以大于 1。它最终代表什么，要结合任务和后续计算来判断。</p>'),
    gradient:()=>wrap('gradient','把“斜率”变成一次看得见的更新','固定输入 x=2、偏置 b=0、正确答案 y=5，只让权重 w 改变。预测是 ŷ=2w，均方误差是 L=(ŷ−y)²。w=1 时预测 2、损失 9；拖动滑杆，看损失和梯度怎样变化。','<label class="bw-slider-label">当前权重 w：<output data-bw-grad-w>1.0</output><input type="range" min="0" max="5" step="0.1" value="1" data-bw-grad-slider aria-label="调整当前参数 w"></label><div class="bw-readouts"><div><small>当前预测</small><strong data-bw-grad-pred>2.00</strong><code>ŷ=2w</code></div><div><small>当前损失</small><strong data-bw-grad-loss>9.00</strong><code>L=(2w−5)²</code></div><div><small>当前斜率</small><strong data-bw-grad-slope>−12.00</strong><code>dL/dw=4(2w−5)</code></div><div><small>走一步后的 w</small><strong data-bw-grad-next>1.60</strong><code>η=0.05</code></div><div><small>新损失</small><strong data-bw-grad-newloss>3.24</strong><span>本例的损失下降了</span></div></div><p class="bw-note">这里用标准平方误差，不含 1/2；固定学习率 0.05。互动只更新 w、暂时固定偏置，完整训练还可以同时更新多个参数。</p>'),
    optimizer:()=>wrap('optimizer','学习率决定这一步走多远','沿用同一个例子：输入 x=2、目标 y=5、偏置 b=0、旧权重 w=1，预测为 2，均方误差为 9，梯度为 −12。更新公式是“新权重 = 旧权重 − 学习率 × 梯度”。拖动滑杆，观察步幅如何改变结果。','<label class="bw-slider-label">学习率 η：<output data-bw-lr-out>0.05</output><input type="range" min="0.01" max="0.50" step="0.005" value="0.05" data-bw-lr-slider aria-label="调整学习率"></label><div class="bw-readouts"><div><small>旧参数 w</small><strong>1.00</strong></div><div><small>梯度</small><strong>−12.00</strong></div><div><small>新权重</small><strong data-bw-lr-next>1.60</strong></div><div><small>新损失</small><strong data-bw-lr-loss>3.24</strong></div></div><p class="bw-note" data-bw-lr-note>此互动固定偏置为 0，只看权重 w；较小的学习率步子短，过大则可能越过低损失区域。</p>'),
    regularization:()=>wrap('regularization','训练题做得好，不代表学会了解题规律','切换到更多训练轮次：训练集错误继续下降，但验证集错误反而上升，说明模型可能开始记住训练例子的细节。','<div class="bw-regularization-toggle"><button type="button" class="bw-primary" data-bw-reg-toggle>多训练一些轮次</button><div class="bw-readouts"><div><small>训练集错误率</small><strong data-bw-reg-train>10%</strong></div><div><small>验证集错误率</small><strong data-bw-reg-val>12%</strong></div></div><p data-bw-reg-copy>当前：两边都表现不错，继续观察验证集变化。</p></div><p class="bw-note">正则化是通过限制或扰动模型的学习方式，减少它对偶然细节的依赖。Dropout、权重衰减和早停机制不同，不能当成同一种操作。</p><section class="bw-early-demo" aria-labelledby="bw-early-title"><h4 id="bw-early-title">patience = 2：连续两次验证没有变好，就停止</h4><p>这里使用“验证准确率越高越好”的例子。第 3 轮达到最高的 86%；后面连续两轮下降，于是停止，并恢复第 3 轮保存的模型状态。</p><div class="bw-adam-controls" role="group" aria-label="逐轮查看早停记录"><button type="button" data-bw-early-step="0" aria-pressed="true">第 1 轮</button><button type="button" data-bw-early-step="1" aria-pressed="false">第 2 轮</button><button type="button" data-bw-early-step="2" aria-pressed="false">第 3 轮</button><button type="button" data-bw-early-step="3" aria-pressed="false">第 4 轮</button><button type="button" data-bw-early-step="4" aria-pressed="false">第 5 轮</button></div><div class="bw-ap-table-wrap"><table class="bw-ap-table bw-early-table"><caption>验证集准确率与 patience 计数</caption><thead><tr><th scope="col">轮次</th><th scope="col">验证准确率</th><th scope="col">当前最佳</th><th scope="col">未提升次数</th><th scope="col">决定</th></tr></thead><tbody><tr data-bw-early-row="0" class="is-current"><th scope="row">1</th><td>78%</td><td>78%</td><td>0</td><td>继续</td></tr><tr data-bw-early-row="1"><th scope="row">2</th><td>84%</td><td>84%</td><td>0</td><td>继续</td></tr><tr data-bw-early-row="2"><th scope="row">3</th><td>86%</td><td>86%</td><td>0</td><td>继续（最佳）</td></tr><tr data-bw-early-row="3"><th scope="row">4</th><td>84%</td><td>86%</td><td>1</td><td>再观察一次</td></tr><tr data-bw-early-row="4"><th scope="row">5</th><td>82%</td><td>86%</td><td>2</td><td>停止，恢复第 3 轮</td></tr></tbody></table></div><p class="bw-adam-detail" data-bw-early-detail role="status">第 1 轮：验证准确率 78%，刷新最佳记录，未提升计数归零。</p><p class="bw-note">真实流程会在验证指标不改善时保存/选择最佳 checkpoint。耐心值按验证检查次数计数；若监控的是越低越好的损失，改善方向要反过来判断。</p></section><section class="bw-dropout-demo" aria-labelledby="bw-dropout-title"><h4 id="bw-dropout-title">Dropout：练习时暂时关闭一个节点</h4><p>节点输出是网络中间产生的数。Dropout 在训练期间随机把一些输出暂时变成 0，减少模型只依赖固定几个节点；评估时不会随机关闭。为方便观察，这里按顺序切换被关闭的节点，真实训练的选择是随机的。</p><div class="bw-dropout-nodes" role="group" aria-label="四个神经元节点示意"><span data-bw-dropout-node="0">节点 A<br><b>0.8</b></span><span data-bw-dropout-node="1">节点 B<br><b>0.6</b></span><span data-bw-dropout-node="2">节点 C<br><b>0.9</b></span><span data-bw-dropout-node="3">节点 D<br><b>0.4</b></span></div><button type="button" class="bw-primary" data-bw-dropout-next>换一个被关闭的节点</button><p class="bw-adam-detail" data-bw-dropout-status role="status">示意：训练时暂时关闭节点 A，它本步输出为 0。</p><p class="bw-note">这个动画只解释“暂时失活”的概念；框架还会按 Dropout 概率缩放保留的输出，具体数值由所用接口设置决定。</p></section>'),
    'training-loop':()=>wrap('training-loop','8 张图片怎样变成 4 次更新？','把 8 张带答案的图片分成每批 2 张，共 4 个 batch（小批次）。本例每批更新一次、不做梯度累积；走完 4 批就是一个 epoch（完整遍历一次训练数据）。每批分三次点击演示，只有完成 step 才增加更新计数。','<div class="bw-loop-visual"><div class="bw-loop-counter"><strong data-bw-loop-step>0 / 4</strong><span data-bw-loop-label>准备从第一批开始</span></div><div class="bw-batch-row" data-bw-batches></div><button type="button" class="bw-primary" data-bw-loop-next>开始下一批</button><button type="button" data-bw-loop-reset>重新开始</button></div><ol class="bw-mini-steps"><li>取出图片和标签</li><li>模型计算预测并与答案比较</li><li>算出梯度并更新参数</li><li>4 批完成后，在未参与更新的验证图片上检查效果</li></ol>'),
    image:()=>wrap('image','点一个像素，看看模型实际收到什么','一张彩色图片不是“红色、绿色”这些词，而是逐像素排列的数字。点左侧像素，可查看它的三个颜色数值及 0–1 缩放结果。','<div class="bw-pixel-layout"><div class="bw-pixel-grid" role="group" aria-label="选择 2 行 2 列彩色像素"><button type="button" data-bw-pixel="255,80,60" style="--pixel:#ff503c" aria-label="第 1 行第 1 列像素" aria-pressed="true"></button><button type="button" data-bw-pixel="40,160,220" style="--pixel:#28a0dc" aria-label="第 1 行第 2 列像素" aria-pressed="false"></button><button type="button" data-bw-pixel="40,190,100" style="--pixel:#28be64" aria-label="第 2 行第 1 列像素" aria-pressed="false"></button><button type="button" data-bw-pixel="240,210,60" style="--pixel:#f0d23c" aria-label="第 2 行第 2 列像素" aria-pressed="false"></button></div><div class="bw-pixel-reading"><strong data-bw-pixel-position>第 1 行，第 1 列</strong><p>RGB：<code data-bw-pixel-rgb>255, 80, 60</code></p><p>缩放到 0–1：<code data-bw-pixel-float>1.00, 0.31, 0.24</code></p></div></div><div class="bw-layout-compare"><div><strong>HWC</strong><code>高 × 宽 × 颜色</code><p>每个位置放一组 RGB 数字。</p></div><div><strong>CHW</strong><code>颜色 × 高 × 宽</code><p>先放完红色通道，再放绿色和蓝色。</p></div></div><p class="bw-note">常见 8 位图像用 0–255 表示亮度；除以 255 可变成 0–1。换布局只换轴的位置，不改变像素颜色。</p><section class="bw-standardization-demo" aria-labelledby="bw-standardization-title"><h4 id="bw-standardization-title">把像素减去平均值，再除以标准差</h4><p>以同一颜色通道的三个亮度值 100、120、140 为例。这里按总体标准差计算：平均值是 120，标准差约 16.33。</p><div class="bw-standardization-equation">标准化数值 = (原数值 − 120) ÷ 16.33</div><table class="bw-ap-table bw-standardization-table"><caption>标准化前后对照</caption><thead><tr><th scope="col">像素原值</th><th scope="col">减去平均值</th><th scope="col">除以标准差</th><th scope="col">结果约为</th></tr></thead><tbody><tr><td>100</td><td>−20</td><td>−20 ÷ 16.33</td><td>−1.22</td></tr><tr><td>120</td><td>0</td><td>0 ÷ 16.33</td><td>0</td></tr><tr><td>140</td><td>+20</td><td>+20 ÷ 16.33</td><td>+1.22</td></tr></tbody></table><p class="bw-note">这一步改变数字的中心和尺度，不会移动像素或改变标签。真实项目通常按训练数据、逐颜色通道计算或读取平均值与标准差，并在验证和推理时沿用同一设置。</p></section>'),
    tasks:()=>wrap('tasks','同一张街景图，模型可以回答三种不同问题','先看任务要求的答案长什么样，再谈模型结构。点按钮切换：整张图分类、逐个物体检测、或逐像素分割。','<div class="bw-task-switch" role="group" aria-label="选择视觉任务"><button type="button" data-bw-task="classify" aria-pressed="true">整图分类</button><button type="button" data-bw-task="detect" aria-pressed="false">目标检测</button><button type="button" data-bw-task="segment" aria-pressed="false">像素分割</button></div><div class="bw-task-demo"><svg viewBox="0 0 360 190" role="img" aria-label="蓝天、道路和一辆红色汽车组成的示意街景"><rect width="360" height="190" fill="#dceefa"/><circle cx="295" cy="38" r="22" fill="#f5ca68"/><path d="M0 116H360V190H0Z" fill="#8997a8"/><path d="M0 116H360" stroke="#fff" stroke-width="4" stroke-dasharray="20 18"/><path d="M96 92h142l22 35H76z" fill="#e87d68"/><circle cx="119" cy="132" r="13" fill="#26384d"/><circle cx="229" cy="132" r="13" fill="#26384d"/><rect data-bw-detect-box x="72" y="84" width="196" height="68" fill="none" stroke="#7f5af0" stroke-width="3" stroke-dasharray="7 4"/><path data-bw-seg-mask d="M80 91h158l18 35H78z" fill="#f4c64e" fill-opacity=".62"/></svg><div><strong data-bw-task-title>分类答案：有汽车</strong><p data-bw-task-copy>只回答整张图片里有没有汽车，不指出它在哪里。</p></div></div><div class="bw-task-defs"><span><b>分类</b>：整张图一个答案</span><span><b>检测</b>：每个目标一个类别和矩形框</span><span><b>分割</b>：逐个像素标出属于哪里</span></div>'),
    cnn:()=>wrap('cnn','卷积先只算一个输出格','把 3×3 图像窗口与 3×3 滤镜对应相乘，再把九个乘积相加。这里用“左边亮、右边暗”的滤镜，观察它对竖直边缘的响应。','<div class="bw-conv-layout"><div><strong>输入窗口</strong><div class="bw-number-grid" data-bw-input-grid></div></div><span class="bw-times" aria-hidden="true">×</span><div><strong>滤镜权重</strong><div class="bw-number-grid" data-bw-kernel-grid></div></div><span class="bw-equals" aria-hidden="true">=</span><div class="bw-conv-result"><small>目前乘加到第</small><strong data-bw-conv-count>0 / 9</strong><small>项</small><output data-bw-conv-sum>0</output></div></div><p class="bw-calc-line" data-bw-conv-line>按下“逐项计算”查看每次乘法与累加。</p><button type="button" class="bw-primary" data-bw-conv-next>逐项计算</button><button type="button" data-bw-conv-reset>重置</button><p class="bw-note">本例滤镜产生的总和是 −6。真实卷积层还会加入偏置，并有多组滤镜；窗口移动后，每个位置重复同一套乘加。</p>'),
    pooling:()=>wrap('pooling','一个 2×2 区域怎样缩成一个数？','池化先圈出窗口里的四个数，再按规则选一个代表值。最大池化保留最强响应，平均池化保留平均水平。','<div class="bw-pool-layout"><div class="bw-number-grid"><span>1</span><span>4</span><span>3</span><span>2</span></div><div class="bw-pool-buttons"><button type="button" data-bw-pool="max" aria-pressed="true">最大池化</button><button type="button" data-bw-pool="avg" aria-pressed="false">平均池化</button></div><div class="bw-pool-output"><small>窗口输出</small><strong data-bw-pool-out>4</strong><span data-bw-pool-calc>max(1, 4, 3, 2)</span></div></div><p class="bw-note">本例只有一个窗口。窗口移动时会生成更多输出；步幅决定每次移动多少格，边界不足一整窗时如何处理要看具体设置。<section class="bw-pool-coverage" aria-labelledby="bw-pool-coverage-title"><h4 id="bw-pool-coverage-title">3×3 数字图：窗口和步幅怎样决定输出？</h4><p>这里用 2×2 最大池化窗口，不补边，只放完整窗口。点击右侧输出格，可看到它取自左侧哪四个数。</p><div class="bw-pool-coverage-layout"><div><strong>输入特征图</strong><div class="bw-pool-coverage-grid" role="grid" aria-label="三行三列输入数字" data-bw-pool-coverage-grid><span data-bw-pool-cell="0">1</span><span data-bw-pool-cell="1">2</span><span data-bw-pool-cell="2">3</span><span data-bw-pool-cell="3">4</span><span data-bw-pool-cell="4">5</span><span data-bw-pool-cell="5">6</span><span data-bw-pool-cell="6">7</span><span data-bw-pool-cell="7">8</span><span data-bw-pool-cell="8">9</span></div></div><div class="bw-pool-result-side"><div class="bw-pool-buttons"><button type="button" data-bw-pool-stride="1" aria-pressed="true">步幅 1</button><button type="button" data-bw-pool-stride="2" aria-pressed="false">步幅 2</button></div><strong>输出特征图 <output data-bw-pool-shape>2 × 2</output></strong><div class="bw-pool-results" role="grid" aria-label="池化输出数字" data-bw-pool-results></div></div></div><p class="bw-adam-detail" data-bw-pool-coverage-copy role="status">输出格取输入左上 2×2 窗口，最大值是 5。</p><p class="bw-note">步幅 1 会得到 2×2 输出：[5, 6; 8, 9]；步幅 2 只能放下左上一个完整窗口，得到 1×1 的 5，最右列和最下行没有进入任何窗口。开启 padding 或 ceil_mode 时边界行为会不同。</p><div class="bw-global-pool"><strong>全局平均池化：每个通道各自缩成一个数</strong><div><span>特征 A：1、3、5、7 → 平均值 <b>4</b></span><span>特征 B：2、4、6、8 → 平均值 <b>5</b></span></div></div></section></p>'),
    iou:()=>wrap('iou','交集变大时，IoU 为什么会上升？','两个框面积都设为 100。调节交集面积，先算并集，再用“交集 ÷ 并集”得到重叠比例。','<label class="bw-slider-label">交集面积：<output data-bw-iou-intersection>50</output><input type="range" min="0" max="100" step="5" value="50" data-bw-iou-slider aria-label="调整两个矩形的交集面积"></label><div class="bw-readouts"><div><small>并集面积</small><strong data-bw-iou-union>150</strong><code>100 + 100 − 交集</code></div><div><small>IoU</small><strong data-bw-iou-value>0.333</strong><code>交集 ÷ 并集</code></div></div><p class="bw-note">IoU = Intersection over Union，中文常说“交并比”。两个框完全不重叠时为 0；完全相同且面积非零时为 1。</p>'),
    augmentation:()=>wrap('augmentation','图片翻转时，框也要跟着翻转','图片宽度按 0–1 归一化。目标框中心原来 x=0.20；左右翻转后中心变为 1−0.20=0.80。点按钮观察目标和框一起移动。','<div class="bw-flip-demo"><svg viewBox="0 0 360 190" data-bw-flip-scene role="img" aria-label="图片翻转时，红色汽车和绿色标注框同步移动"><rect width="360" height="190" fill="#e3f0fa"/><rect y="118" width="360" height="72" fill="#7f8996"/><path d="M0 118H360" stroke="#fff" stroke-width="4" stroke-dasharray="22 18"/><g data-bw-flip-car><path d="M56 90h110l20 33H38z" fill="#e87d68"/><circle cx="70" cy="130" r="12" fill="#26384d"/><circle cx="153" cy="130" r="12" fill="#26384d"/></g><rect data-bw-flip-box x="32" y="82" width="164" height="68" fill="none" stroke="#30876e" stroke-width="3"/></svg><p>框中心 x：<strong data-bw-flip-x>0.20</strong>　宽度：<strong>0.45</strong></p><button type="button" class="bw-primary" data-bw-flip-toggle>水平翻转</button></div><p class="bw-note">翻转后，框宽高不变，中心横坐标变为 1−x；若只翻图片不翻标注，模型就会被教错。<section class="bw-hsv-demo" aria-labelledby="bw-hsv-title"><h4 id="bw-hsv-title">颜色增强：色相、饱和度、明度分别改变什么？</h4><p>这幅小街景只用来观察方向：改色相会绕颜色环转，改饱和度会让颜色变灰或更鲜艳，改明度会让画面变暗或变亮。</p><svg viewBox="0 0 320 180" role="img" aria-label="由蓝天、绿地、道路和红车组成的颜色增强示意图"><g data-bw-hsv-art><rect width="320" height="180" fill="#90c7ee"/><circle cx="258" cy="34" r="20" fill="#ffd65a"/><path d="M0 112 Q80 65 155 112 T320 105 V180 H0Z" fill="#76b76b"/><rect y="128" width="320" height="52" fill="#667383"/><path d="M0 153H320" stroke="#f7efce" stroke-width="3" stroke-dasharray="18 14"/><path d="M94 104h92l18 25H78z" fill="#e65f52"/><circle cx="105" cy="132" r="9" fill="#26384d"/><circle cx="172" cy="132" r="9" fill="#26384d"/></g></svg><label class="bw-slider-label">色相 H：<output data-bw-hsv-h-out>0°</output><input type="range" min="-60" max="60" step="5" value="0" data-bw-hsv-h aria-label="调整示意图色相"></label><label class="bw-slider-label">饱和度 S：<output data-bw-hsv-s-out>1.0×</output><input type="range" min="0" max="2" step="0.1" value="1" data-bw-hsv-s aria-label="调整示意图饱和度"></label><label class="bw-slider-label">明度 V：<output data-bw-hsv-v-out>1.0×</output><input type="range" min="0.5" max="1.5" step="0.1" value="1" data-bw-hsv-v aria-label="调整示意图明度"></label><p class="bw-note">图中滑杆用浏览器颜色滤镜近似演示变化方向，并非 YOLOv5 的精确增强公式。真实训练通常随机采样增强幅度；每次先改变一个因素，比较前后图像和标签。</p></section></p>'),
    metrics:()=>wrap('metrics','调低门槛，找到更多目标，也可能多报错','账本里有 3 个真实目标。每个预测按置信分数从高到低排列；调整门槛，观察“报出的结果”与“找到的真实目标”如何改变。','<label class="bw-slider-label">保留置信分数 ≥ <output data-bw-threshold-out>0.70</output><input type="range" min="0" max="2" step="1" value="0" data-bw-threshold-slider aria-label="选择预测门槛：高、中或低"></label><div class="bw-prediction-ledger" data-bw-ledger></div><div class="bw-readouts"><div><small>查准率 Precision</small><strong data-bw-precision>100%</strong><span>保留预测中有多少是真的</span></div><div><small>查全率 Recall</small><strong data-bw-recall>66.7%</strong><span>真实目标中找到多少个</span></div><div><small>F1</small><strong data-bw-f1>80.0%</strong><span>查准率与查全率的折中分数</span></div></div><section class="bw-ap-example" aria-labelledby="bw-ap-title"><h4 id="bw-ap-title">再看完整排序：AP 怎样把整条曲线合起来？</h4><p>下面固定有 3 个真实目标，把 4 个预测按分数从高到低排列。这个表不随上方门槛滑杆变化；它展示从严到松逐步加入预测时的累计结果。</p><div class="bw-ap-table-wrap"><table class="bw-ap-table"><caption>每加入一个预测，就重新统计截至当前的 Precision 与 Recall</caption><thead><tr><th scope="col">顺序</th><th scope="col">分数</th><th scope="col">结果</th><th scope="col">累计 Precision</th><th scope="col">累计 Recall</th></tr></thead><tbody><tr><th scope="row">1</th><td>0.95</td><td>命中 TP</td><td>1/1 = 1.00</td><td>1/3 = 0.33</td></tr><tr><th scope="row">2</th><td>0.82</td><td>命中 TP</td><td>2/2 = 1.00</td><td>2/3 = 0.67</td></tr><tr><th scope="row">3</th><td>0.61</td><td>误报 FP</td><td>2/3 = 0.67</td><td>2/3 = 0.67</td></tr><tr><th scope="row">4</th><td>0.34</td><td>命中 TP</td><td>3/4 = 0.75</td><td>3/3 = 1.00</td></tr></tbody></table></div><p>按 Precision 包络线的阶梯面积近似：Recall 从 0 到 1/3、再到 2/3 时高度都是 1.00；最后从 2/3 到 1 的高度是 0.75。因此 AP ≈ (1/3×1.00) + (1/3×1.00) + (1/3×0.75) = 0.917。只有一个类别时，mAP 就等于这个 AP；多个类别时，mAP 是各类别 AP 的平均。真实评估会按指定 IoU 条件和实现采用的插值规则统计，数字可能略有差异。</p></section><p class="bw-note">这是便于手算的配对示例。正式评估会在一系列门槛下绘制 PR 曲线，再按数据集协议计算 AP/mAP。</p>'),
    'data-quality':()=>wrap('data-quality','相邻视频帧分到两边，验证成绩会虚高','同一段连续拍摄的视频会产生很多非常相似的图片。如果把相邻帧随机分到训练集和验证集，模型可能在验证时见过几乎相同的场景。','<div class="bw-split-compare"><div><button type="button" data-bw-split="random" aria-pressed="true">随机拆图片</button><button type="button" data-bw-split="group" aria-pressed="false">按拍摄来源拆</button></div><div class="bw-frame-groups" data-bw-frame-groups></div><p data-bw-split-copy>随机拆分会让相邻帧同时出现在训练与验证中，检查结果不够独立。</p></div><p class="bw-note">更稳妥的做法是先按拍摄视频、地点或时间分组，再把整组分到一侧。哈希和统计是帮助找重复或偏差的工具，不能替代数据来源判断。</p><section class="bw-hard-negative-demo" aria-labelledby="bw-hard-negative-title"><h4 id="bw-hard-negative-title">困难负例：看起来像目标，但答案是“没有”</h4><p>如果道路阴影很像车辆，模型容易把它误报成车。把这类真实背景图放进训练并标记为没有目标，能帮助模型学会区分相似外观。</p><div class="bw-hard-negative-scene" data-bw-hard-negative-scene><svg viewBox="0 0 300 130" role="img" aria-label="道路上像汽车形状的阴影，但没有真实汽车"><rect width="300" height="130" fill="#dcecf5"/><rect y="52" width="300" height="78" fill="#687582"/><path d="M0 91H300" stroke="#f6edcf" stroke-width="3" stroke-dasharray="20 15"/><path d="M92 50h94l22 30H72z" fill="#263548" opacity=".54"/><text x="15" y="25" fill="#40546a" font-size="12">这是一片阴影，不是真车</text></svg></div><button type="button" class="bw-primary" data-bw-hard-negative-toggle>查看正确标签</button><p data-bw-hard-negative-copy role="status">模型可能把阴影误报成车；数据标签仍应写“没有车辆”。</p><p class="bw-note">困难负例按真实内容标注，不是把真实目标故意错标成背景。哈希查重和类别统计也不能代替人工查看边界案例。</p></section><section class="bw-class-distribution" aria-labelledby="bw-class-distribution-title"><h4 id="bw-class-distribution-title">用数量图找训练资料里的缺口</h4><p>下面是教学用的标注框数量，不是本站数据：先看类别，再看目标大小。每条横条都按该组最大数量缩放。</p><div class="bw-class-bars" aria-label="不同类别的标注框数量"><div><span>汽车　800 个框</span><i><b style="width:100%"></b></i></div><div><span>自行车　120 个框</span><i><b style="width:15%"></b></i></div><div><span>交通灯　40 个框</span><i><b style="width:5%"></b></i></div></div><div class="bw-class-bars bw-size-bars" aria-label="不同大小目标的数量"><div><span>小目标　600</span><i><b style="width:100%"></b></i></div><div><span>中目标　260</span><i><b style="width:43.3%"></b></i></div><div><span>大目标　100</span><i><b style="width:16.7%"></b></i></div></div><p class="bw-note">数量少的类别或尺寸可能更容易漏检，但只凭数量不能判断原因；还要检查标签是否正确、拍摄环境是否相似，以及错误图里漏检和误报各占多少。</p></section>'),
    transfer:()=>wrap('transfer','迁移学习：保留会的部分，再学新答案','旧模型已学到边缘、纹理等视觉线索。换成新任务时，可以先只训练新的输出头；再逐步解冻前面层。点按钮比较参数状态。','<div class="bw-transfer-layers" data-bw-transfer-state="frozen"><div><b>输入层</b><span>通用线索</span></div><div><b>中间层</b><span>纹理与部件</span></div><div><b>输出头</b><span>新类别</span></div></div><p data-bw-transfer-copy role="status">当前：前面两层冻结，只更新新的输出头。</p><button type="button" class="bw-primary" data-bw-transfer-toggle>逐步解冻前面层</button><p class="bw-note">“冻结参数”通常指不计算或不应用这些参数的梯度更新；BatchNorm 的运行统计、训练/评估模式是另一项设置，不能自动视为同一回事。</p>'),
    architecture:()=>wrap('architecture','YOLOv5 可以先记成：提线索、合线索、给候选答案','先理解三个部分各自做什么，再进入 YAML 层号。点模块名称，查看它在整条路径里的职责。','<div class="bw-yolo-flow" aria-label="YOLOv5 三部分数据流"><button type="button" data-bw-module="backbone" aria-pressed="true"><strong>Backbone</strong><span>提取线索</span></button><i aria-hidden="true">→</i><button type="button" data-bw-module="neck" aria-pressed="false"><strong>Neck</strong><span>融合尺度</span></button><i aria-hidden="true">→</i><button type="button" data-bw-module="head" aria-pressed="false"><strong>Detect Head</strong><span>预测候选</span></button></div><div class="bw-module-explain"><strong data-bw-module-title>Backbone：从像素提特征</strong><p data-bw-module-copy>Conv 逐步计算局部线索，C3 在分支与合并中提炼特征，SPPF 用多次池化扩大可见范围。</p></div><div class="bw-module-tags"><span>C3：拆分 → 变换 → 拼接</span><span>SPPF：池化汇集不同范围</span><span>Neck：上采样与拼接进行多尺度融合</span><span>Detect：位置、物体性、类别</span></div><p class="bw-note">P3、P4、P5 是不同分辨率的检测特征图；先看懂大中小目标的信息流，再读网格和 anchor。</p>'),
    anchors:()=>wrap('anchors','网格负责“在哪一格”，anchor 提供“从多大开始”','图片左上角是 (0,0)，向右 x 增大、向下 y 增大。目标中心在 (0.62, 0.37)，点格子看看它落在哪里。','<div class="bw-anchor-layout"><div class="bw-anchor-grid" role="group" aria-label="四行四列目标中心网格" data-bw-anchor-grid></div><div><strong data-bw-anchor-cell>目标中心落在第 2 行、第 3 列</strong><p>归一化中心：(0.62, 0.37)</p><p>网格宽高：4 × 4</p></div></div><p class="bw-note">每个网格位置还会结合若干宽高 anchor 形成候选。anchor 是调整起点，不是最终检测框；训练匹配规则还会看目标尺寸与邻近网格。</p><section class="bw-anchor-match" aria-labelledby="bw-anchor-match-title"><h4 id="bw-anchor-match-title">同一个目标，哪种宽高模板更贴近？</h4><p>教学例子：640×640 图片中的目标框宽 0.30、高 0.20，换算为 192×128 像素。先把中心对齐，再比较两种模板的面积重叠；这帮助理解“尺寸匹配”，不是 YOLOv5 源码的完整分配算法。</p><div class="bw-adam-controls" role="group" aria-label="选择一个宽高 anchor 模板"><button type="button" data-bw-anchor-template="small" aria-pressed="true">模板 A：160×120</button><button type="button" data-bw-anchor-template="large" aria-pressed="false">模板 B：320×160</button></div><svg viewBox="0 0 320 160" role="img" aria-label="彩色目标框与当前 anchor 模板叠加比较"><rect x="0" y="0" width="320" height="160" rx="5" fill="#fbfafc" stroke="#ddd7e8"/><rect x="64" y="16" width="192" height="128" fill="#efad6155" stroke="#d88b35" stroke-width="3"/><rect data-bw-anchor-template-rect x="80" y="20" width="160" height="120" fill="#67aa8b55" stroke="#348566" stroke-width="3"/><text x="72" y="14" font-size="9" fill="#945916">目标 192×128</text><text data-bw-anchor-template-label x="84" y="34" font-size="9" fill="#267052">模板 A 160×120</text></svg><div class="bw-readouts"><div><small>目标框面积</small><strong>24,576 px²</strong></div><div><small>模板与目标的 IoU</small><strong data-bw-anchor-iou>0.781</strong></div></div><p class="bw-adam-detail" data-bw-anchor-match-copy role="status">中心对齐时，模板 A 完全落在目标框内：交集 19,200，面积并集 24,576，IoU≈0.781。</p><p class="bw-note">模板 B 完全覆盖目标框时，IoU≈0.480，因此这个教学例子更接近 A。真实 YOLOv5 还会按宽高比例门槛、网格位置和邻格规则分配候选；不要把这张简化比较图误当成完整源码算法。</p></section>'),
    'yolo-loss':()=>wrap('yolo-loss','一个候选框要回答三个不同问题','用同一个候选框记账：位置准不准？这里有没有目标？如果有，是什么类别？点每一项，看需要和什么答案比较。','<div class="bw-loss-parts" role="group" aria-label="查看 YOLO 损失组成"><button type="button" data-bw-loss-part="box" aria-pressed="true">框的位置</button><button type="button" data-bw-loss-part="obj" aria-pressed="false">物体性</button><button type="button" data-bw-loss-part="cls" aria-pressed="false">类别</button></div><div class="bw-loss-explain"><strong data-bw-loss-title>框的位置</strong><p data-bw-loss-copy>把预测框和真实框比较。YOLOv5 的具体实现使用 CIoU 相关定位损失，既看重叠，也考虑中心距离和形状比例。</p></div><div class="bw-loss-checks"><span>定位：预测框 ↔ 真实框</span><span>物体性：预测分数 ↔ 目标软值</span><span>类别：类别分数 ↔ 类别标签</span></div><p class="bw-note">YOLOv5 常见实现中的物体性目标会根据匹配框的 IoU 形成软值，不能简单说成每处都只用 0 或 1。具体权重与细节以所读代码版本为准。</p><section class="bw-yolo-loss-worked" aria-labelledby="bw-yolo-loss-worked-title"><h4 id="bw-yolo-loss-worked-title">同一个候选框，三本损失账怎样算？</h4><p>下面是一组为教学构造的单候选数字，宽高比例相同，位置和类别答案都明确。先分开看三项，再理解为什么源码会给它们不同权重。</p><div class="bw-ap-table-wrap"><table class="bw-ap-table bw-yolo-loss-table"><caption>一个正样本候选的简化计算</caption><thead><tr><th scope="col">要回答的问题</th><th scope="col">代入的数字</th><th scope="col">得到的示意损失</th></tr></thead><tbody><tr><th scope="row">框的位置准不准？</th><td>真框中心 (0.500,0.500)，预测中心 (0.545,0.522)，宽高均为 0.400×0.300；IoU≈0.698，中心距离惩罚≈0.008，形状比例相同</td><td>CIoU≈0.690，因此定位损失 1−CIoU≈0.310</td></tr><tr><th scope="row">这里有没有目标？</th><td>物体性 logit=1，Sigmoid 后概率≈0.731；教学目标值设为 0.700</td><td>BCEWithLogitsLoss≈0.613</td></tr><tr><th scope="row">目标是什么类别？</th><td>类别 logits=[1,−0.5]，标签=[1,0]；概率约为 [0.731,0.378]</td><td>两个 BCE 约为 0.313 与 0.474；平均≈0.394</td></tr></tbody></table></div><p>若仅为演示把三项权重都设成 1，总和约为 0.310+0.613+0.394=1.317。它只表示“分项相加”的流程，不是某次 YOLOv5 训练的实际 loss 数值。</p><p class="bw-note">真实训练会在许多位置与匹配目标上累计损失，并使用超参数权重；物体性软目标、匹配结果和具体项还取决于仓库版本。预测中心与真框重叠面积的数值均为本教学例子，不应代替源码复算。</p></section>'),
    'yolo-augment':()=>wrap('yolo-augment','Mosaic 把四张图放进同一次训练输入','拼接增强不仅改变像素，也要同步移动每个框。点按钮切换，比较一张完整图片与四个来源区域。','<div class="bw-mosaic-demo"><div class="bw-mosaic-canvas" data-bw-mosaic><span class="mosaic-a">道路</span><span class="mosaic-b">车辆</span><span class="mosaic-c">行人</span><span class="mosaic-d">路牌</span><i aria-hidden="true"></i><i aria-hidden="true"></i></div><button type="button" class="bw-primary" data-bw-mosaic-toggle>开启 Mosaic 拼接</button><p data-bw-mosaic-copy>当前是一张原图；标注框围住原图里的目标。</p></div><div class="bw-layout-compare"><div><strong>data.yaml</strong><p>说明读哪些数据和类别名称。</p></div><div><strong>model.yaml</strong><p>说明网络层和结构配置。</p></div><div><strong>hyp.yaml</strong><p>说明训练超参数和增强设置。</p></div></div><p class="bw-note">先固定数据、模型和训练轮数，只改一个增强选项，才能判断变化来自哪里。</p><section class="bw-image-budget-demo" aria-labelledby="bw-image-budget-title"><h4 id="bw-image-budget-title">输入边长翻倍，像素数会变成几倍？</h4><p>保持宽高比为正方形时，输入边长从 320 增到 640，宽和高都翻倍，因此像素总数变成 4 倍；边长 960 则约为 9 倍。</p><div class="bw-adam-controls" role="group" aria-label="选择输入图像边长"><button type="button" data-bw-image-size="320" aria-pressed="true">320</button><button type="button" data-bw-image-size="640" aria-pressed="false">640</button><button type="button" data-bw-image-size="960" aria-pressed="false">960</button></div><div class="bw-image-budget-track"><span data-bw-image-budget-bar></span></div><p class="bw-adam-detail" data-bw-image-budget-copy role="status">320×320 = 102,400 个像素，作为 1 倍基准。</p><p class="bw-note">输入像素数能帮助理解计算预算趋势；实际速度和显存还受网络层、batch、硬件、精度和实现影响，不能只按像素比例推断耗时。</p></section>'),
    'train-yolo':()=>wrap('train-yolo','一条训练命令，其实是给程序填几项设置','命令行是把参数写在程序名后面的启动方式。点每一项，先理解它的作用；完整运行还需要 Python 环境、数据配置和权重文件。','<div class="bw-command-line"><code>python train.py --img 640 --batch 16 --epochs 100 --data data.yaml --weights yolov5s.pt</code></div><div class="bw-command-parts"><button type="button" data-bw-command="python">python</button><button type="button" data-bw-command="script">train.py</button><button type="button" data-bw-command="img">--img 640</button><button type="button" data-bw-command="batch">--batch 16</button><button type="button" data-bw-command="epochs">--epochs 100</button><button type="button" data-bw-command="data">--data data.yaml</button><button type="button" data-bw-command="weights">--weights yolov5s.pt</button></div><div class="bw-module-explain"><strong data-bw-command-title>python：启动 Python 程序的解释器</strong><p data-bw-command-copy>先确认当前终端使用的是已安装项目依赖的 Python 环境。</p></div><p class="bw-note">这里只是拆解一条示例命令，参数名和默认值会随 YOLOv5 代码版本改变；先在本地仓库用 train.py --help 核对。</p><section class="bw-yolo-quickstart" aria-labelledby="bw-yolo-quickstart-title"><h4 id="bw-yolo-quickstart-title">从准备环境到跑一轮小样本</h4><ol><li><b>打开仓库终端：</b>先进入包含 train.py 的 YOLOv5 文件夹。</li><li><b>准备独立环境：</b>在终端运行 <code>python -m venv .venv</code>，按系统激活它；再运行 <code>python -m pip install -r requirements.txt</code>。</li><li><b>确认当前版本的参数：</b>运行 <code>python train.py --help</code>，看仓库是否支持下面示例里的选项；确认 data YAML 指向确实存在的数据。</li><li><b>观察第一次输出：</b>训练日志会按轮次打印损失和验证指标；训练结果通常保存到 <code>runs/train/exp*</code>，文件夹编号会避开已有结果。</li></ol><pre class="bw-yolo-command-example"><code>python train.py --imgsz 64 --batch-size 2 --epochs 1 --workers 0 --device cpu --data data/coco128.yaml --weights yolov5n.pt</code></pre><p>这条命令用 64 像素输入、每批 2 张图、训练 1 轮并使用 CPU，方便检查流程；它不会代表正式训练效果。数据和预训练权重须已存在或按仓库设置下载，否则命令会在读文件时失败。</p><p class="bw-note">如果没有预训练权重文件，可按当前版本提供模型配置并设置从头训练；先核对 train.py --help 和仓库 README。Windows PowerShell、命令提示符、macOS/Linux 的环境激活写法不同，网站不假设读者使用同一种终端。</p></section>'),
    quaternion:()=>wrap('quaternion','同一个绕 Z 轴的 90° 旋转，两种写法','先约定：右手坐标系、主动旋转、绕 Z 轴正向旋转、向量写成列向量，四元数顺序为 (w,x,y,z)。滑动角度，看向量和四元数的四个分量一起变化。','<label class="bw-slider-label">绕 Z 轴角度：<output data-bw-q-angle>90°</output><input type="range" min="0" max="180" step="5" value="90" data-bw-q-slider aria-label="调整绕 Z 轴旋转角度"></label><div class="bw-quaternion-demo"><svg viewBox="0 0 240 200" role="img" aria-label="绕 Z 轴旋转的二维投影"><path d="M35 100H215M120 180V20" stroke="#b9c2cd" stroke-width="2"/><path d="M120 100H190" stroke="#e0a74e" stroke-width="4" data-bw-q-vector/><circle cx="190" cy="100" r="7" fill="#7666b2" data-bw-q-point/><text x="205" y="118">x</text><text x="126" y="27">y</text><circle cx="120" cy="100" r="3" fill="#34455d"/></svg><div><p>四元数 q=(w, 0, 0, z)</p><strong data-bw-q-components>q=(0.707, 0, 0, 0.707)</strong><p>旋转后向量：<strong data-bw-q-result>(0, 1, 0)</strong></p></div></div><div class="bw-layout-compare"><div><strong>欧拉角</strong><p>绕各轴转多少；三维时要注明旋转顺序，某些姿态会发生万向节锁。</p></div><div><strong>单位四元数</strong><p>用四个相关数编码旋转；插值和组合方便，但分量不是四个独立角度。</p></div></div><p class="bw-note">本例 z=sin(θ/2)、w=cos(θ/2)，旋转 (1,0,0) 后得到 (cos θ,sin θ,0)。不同库可能使用 (x,y,z,w) 顺序，调用前要查清约定。</p>'),
    dataset:()=>wrap('dataset','一张图片、一个标签文件和一个 YAML 怎样对上？','目录树说明图片在哪里；同名 txt 文件保存每个目标；data YAML 告诉训练脚本类别和数据路径。','<div class="bw-file-tree"><pre>dataset/\n├─ images/\n│  ├─ train/road_01.jpg\n│  └─ val/road_02.jpg\n├─ labels/\n│  ├─ train/road_01.txt\n│  └─ val/road_02.txt\n└─ data.yaml</pre><div><strong>road_01.txt 一行</strong><code>0 0.50 0.50 0.20 0.30</code><p>类别编号、框中心 x/y、宽、高；坐标按图片宽高归一化到 0–1。</p><strong>data.yaml</strong><code>path · train · val · names</code><p>指定根目录、训练/验证列表和类别名称。</p></div></div><p class="bw-note">图片与标签要同名、分目录配对；类别编号从 0 开始。YAML 缩进和相对路径基准必须按实际仓库版本核对。</p><section class="bw-dataset-box-demo" aria-labelledby="bw-dataset-box-title"><h4 id="bw-dataset-box-title">把标签中的数字映回图片上的框</h4><p>假设图片是 640×480 像素，YOLO 标签的后四个数依次是中心 x、中心 y、框宽、框高，并都除以对应图像尺寸写成 0 到 1 的比例。</p><label class="bw-slider-label">中心 x：<output data-bw-dataset-x-out>0.50</output><input type="range" min="0.20" max="0.80" step="0.05" value="0.50" data-bw-dataset-x-slider aria-label="移动目标框的中心横坐标"></label><svg viewBox="0 0 320 240" role="img" aria-label="640 乘 480 图像中的目标框示意"><rect width="320" height="240" rx="8" fill="#eef3f5"/><path d="M0 60H320M0 120H320M0 180H320M80 0V240M160 0V240M240 0V240" stroke="#d9e1e5" stroke-width="1"/><rect data-bw-dataset-box x="128" y="84" width="64" height="72" fill="#e9786250" stroke="#d3614f" stroke-width="3"/><circle data-bw-dataset-center cx="160" cy="120" r="4" fill="#a63f35"/></svg><div class="bw-readouts"><div><small>TXT 标签</small><strong data-bw-dataset-line>0 0.50 0.50 0.20 0.30</strong></div><div><small>像素中的中心与框尺寸</small><strong data-bw-dataset-pixels>(320, 240)；128×144 px</strong></div></div><p class="bw-note">这里类别编号 0 是第一类；框中心横坐标 0.50 对应 640×0.50=320 像素。上下移动、宽高换算也使用各自对应的图像尺寸。</p></section>'),
    inference:()=>wrap('inference','模型分数不是最后画在图片上的框','推理会经过输入整理、网络打分、筛候选、去重、坐标还原。点流程步骤，按同一张图片追踪发生了什么。','<div class="bw-inference-steps" role="group" aria-label="选择推理步骤"><button type="button" data-bw-inference="0" aria-pressed="true">① 预处理</button><button type="button" data-bw-inference="1" aria-pressed="false">② 模型输出</button><button type="button" data-bw-inference="2" aria-pressed="false">③ 阈值筛选</button><button type="button" data-bw-inference="3" aria-pressed="false">④ NMS 与坐标还原</button></div><div class="bw-module-explain"><strong data-bw-inference-title>预处理：把图片整理成训练时约定的数字</strong><p data-bw-inference-copy>调整尺寸、颜色通道和数值范围；如果训练时用了补边，推理后要记录补边比例以便还原框。</p></div><p class="bw-note">置信度门槛控制保留哪些候选；IoU 门槛控制哪些重叠框视为重复。两个门槛解决不同问题。</p>'),
    debugging:()=>wrap('debugging','先从现象开始，沿数据流逐步找原因','把“没有框”拆成可检查的环节。一次检查一层，优先看能直接验证的输入、输出和阈值。','<div class="bw-debug-tree"><button type="button" data-bw-debug="0" aria-pressed="true">没有检测框</button><button type="button" data-bw-debug="1" aria-pressed="false">loss 变成 NaN</button><button type="button" data-bw-debug="2" aria-pressed="false">类别总是错</button></div><div class="bw-module-explain"><strong data-bw-debug-title>第一步：确认输入真的读到了目标</strong><p data-bw-debug-copy>打开原图与标签核对配对、类别编号和框位置；再检查预处理后的图像是否仍清晰可见。</p></div><p class="bw-note">None 表示没有值，0 是一个有效数；NaN/Inf 是非有限数。看见 0 不应直接判定为计算失败。</p>')
  };
  demos['optimizer-momentum']=()=>wrap('optimizer-momentum','Adam 怎样记录近期梯度？','先看梯度及其平方怎样形成平滑记录；再阅读正文中的偏差修正和参数更新。','<section class="bw-adam-demo" aria-labelledby="bw-adam-title"><h4 id="bw-adam-title">Adam 如何记住最近的梯度？</h4><p>为了把算术看清楚，设连续三步的梯度是 <code>+2、0、−2</code>，并用简化的 <code>β₁=β₂=0.5</code>、<code>m₀=v₀=0</code>。m₀、v₀ 是开始前尚无历史数据时设定的初始记录。每一步都把一半旧记录和一半新数值合起来。</p><div class="bw-adam-controls" role="group" aria-label="选择 Adam 统计量演示步骤"><button type="button" data-bw-adam-step="0" aria-pressed="true">第 1 步</button><button type="button" data-bw-adam-step="1" aria-pressed="false">第 2 步</button><button type="button" data-bw-adam-step="2" aria-pressed="false">第 3 步</button></div><div class="bw-readouts bw-adam-readouts"><div><small>本步梯度 g<sub>t</sub></small><strong data-bw-adam-gradient>+2</strong></div><div><small>方向平滑记录 m<sub>t</sub></small><strong data-bw-adam-m>1</strong></div><div><small>平方大小记录 v<sub>t</sub></small><strong data-bw-adam-v>2</strong></div></div><p class="bw-adam-detail" data-bw-adam-detail role="status">第 1 步：m₁=0.5×0+0.5×2=1；v₁=0.5×0+0.5×2²=2。</p><div class="bw-ap-table-wrap"><table class="bw-ap-table bw-adam-table"><caption>三步完整记录；当前选中行会高亮</caption><thead><tr><th scope="col">步骤</th><th scope="col">梯度 g<sub>t</sub></th><th scope="col">一阶矩 m<sub>t</sub></th><th scope="col">二阶原始矩 v<sub>t</sub></th></tr></thead><tbody><tr data-bw-adam-row="0" class="is-current"><th scope="row">1</th><td>+2</td><td>1</td><td>2</td></tr><tr data-bw-adam-row="1"><th scope="row">2</th><td>0</td><td>0.5</td><td>1</td></tr><tr data-bw-adam-row="2"><th scope="row">3</th><td>−2</td><td>−0.75</td><td>2.5</td></tr></tbody></table></div><p class="bw-note">m 平滑保留梯度方向，v 平滑累计逐项平方后的大小；v 不是减去均值后的统计方差。真实 Adam 还会做偏差修正，再结合学习率计算参数更新；这个小表只演示 m、v 怎样形成，β 使用便于手算的教学值 0.5，不是 PyTorch 常用默认值 0.9、0.999。</p></section>');
  demos['gradient-diagnostics']=()=>wrap('gradient-diagnostics','亲手操作：参数、计算图和梯度分别怎样变化？','输入 x=2、目标 y=5、偏置固定为 0，只训练 w。下面用普通 SGD、学习率 0.05 演示，不含动量和权重衰减。',String.raw`
    <p>先试：前向 → 反向 → 再次前向 → 再次反向。观察梯度从 −12 累加成 −24，而权重仍是 1。然后清零，再做前向 → 反向 → 更新，核对权重变成 1.6。</p>
    <div class="bw-ai-flow"><div><b>前向</b><span>输入和参数 → 预测、损失</span><small>记录本次计算关系</small></div><i aria-hidden="true">→</i><div><b>反向</b><span>损失 → 参数梯度</span><small>累加进 .grad</small></div><i aria-hidden="true">→</i><div><b>更新</b><span>旧参数、梯度 → 新参数</span><small>SGD：\(w\leftarrow w-0.05g\)</small></div></div>
    <div class="bw-adam-controls" role="group" aria-label="操作梯度台账"><button type="button" data-bw-ledger-action="forward">① 前向：计算预测和损失</button><button type="button" data-bw-ledger-action="backward">② backward：累加梯度</button><button type="button" data-bw-ledger-action="clear">zero_grad：清除梯度</button><button type="button" data-bw-ledger-action="step">③ step：更新参数</button><button type="button" data-bw-ledger-action="reset">恢复初始状态</button></div>
    <div class="bw-readouts"><div><small>当前参数 w</small><strong data-bw-ledger-w>1.000</strong><span>只有 step 会更新它</span></div><div><small>已存梯度 .grad</small><strong data-bw-ledger-grad>None</strong><span>None 表示尚无已存梯度</span></div><div><small>上次前向的损失</small><strong data-bw-ledger-loss>尚未计算</strong><span data-bw-ledger-graph>先做前向</span></div></div>
    <p class="bw-note" role="status" aria-live="polite" data-bw-ledger-status>先预测：只做前向会改变 w 吗？点击后看台账。</p>
    <div class="bw-ap-table-wrap"><table class="bw-ap-table"><caption>最近 6 次操作；每行显示操作后的状态</caption><thead><tr><th scope="col">操作</th><th scope="col">参数 w</th><th scope="col">已存梯度</th><th scope="col">上次前向损失</th></tr></thead><tbody data-bw-ledger-log></tbody></table></div>
    <details class="depth-advanced"><summary>为什么“再次前向”和“重复反向同一份 loss”不一样？</summary><p>计算图记录一次前向里各个数怎样算出来。这个平方误差例子的反向需要保存误差值；默认反向后会释放这些中间数据，因此不能直接对同一份 loss 再反向。重新前向会建立一份新的计算图，但不会自动清理参数里已存的 .grad，所以新梯度仍会相加。普通梯度累积不需要 retain_graph=True。</p></details>
    <p class="bw-note">这是浏览器中的算术演示，不是在运行 PyTorch。采用 zero_grad(set_to_none=True) 的清理方式；step 不自动清梯度，也不会改写上次记录的 loss。更新后请重新前向，观察新损失。这里多次不清零累加的是梯度之和；模拟更大批次的均值损失还需要按样本数正确缩放，见后面的梯度累积课。</p>`);
  const shapeData={
    scalar:{shape:'()',values:['7'],read:'一个标量：只有一个数，不含行、列或通道轴。'},
    row:{shape:'(3,)',values:['2','5','8'],read:'一维向量：形状 (3,)，只有一条长度为 3 的轴。'},
    table:{shape:'(2, 3)',values:['1','2','3','4','5','6'],read:'二维表格：2 行、每行 3 个数；总数 2×3=6。'},
    image:{shape:'(2, 2, 3)',values:['R','G','B','R','G','B','R','G','B','R','G','B'],read:'彩色图片例子：高 2、宽 2、每像素 3 个颜色数；真实含义取决于轴约定。'}
  };
  function render(lesson){const id=typeof lesson==='string'?lesson:lesson?.id;return demos[id]?demos[id]():'';}
  function initTensor(root){const buttons=root.querySelectorAll('[data-bw-shape]'),grid=root.querySelector('[data-bw-shape-grid]'),read=root.querySelector('[data-bw-shape-readout]');function update(id){const item=shapeData[id]||shapeData.scalar;buttons.forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.bwShape===id)));grid.dataset.shape=id;grid.innerHTML=item.values.map((value,index)=>'<span>'+esc(value)+'</span>').join('');read.textContent='形状 '+item.shape+'。'+item.read;}buttons.forEach(button=>button.addEventListener('click',()=>update(button.dataset.bwShape)));update('scalar');}
  function initNetwork(root){const x=root.querySelector('[data-bw-net-x]'),w=root.querySelector('[data-bw-net-w]'),b=root.querySelector('[data-bw-net-b]');const update=()=>{const xv=Number(x.value),wv=Number(w.value),bv=Number(b.value),z=xv*wv+bv,p=1/(1+Math.exp(-z));root.querySelector('[data-bw-net-x-out]').textContent=xv.toFixed(1);root.querySelector('[data-bw-net-w-out]').textContent=wv.toFixed(1);root.querySelector('[data-bw-net-b-out]').textContent=bv.toFixed(1).replace('-','−');root.querySelector('[data-bw-net-z]').textContent=z.toFixed(2).replace('-','−');root.querySelector('[data-bw-net-p]').textContent=p.toFixed(3);};[x,w,b].forEach(slider=>slider.addEventListener('input',update));update();}
  function initGradient(root){const slider=root.querySelector('[data-bw-grad-slider]');const update=()=>{const w=Number(slider.value),prediction=2*w,g=4*(2*w-5),next=w-0.05*g;root.querySelector('[data-bw-grad-w]').value=w.toFixed(1);root.querySelector('[data-bw-grad-w]').textContent=w.toFixed(1);root.querySelector('[data-bw-grad-pred]').textContent=prediction.toFixed(2);root.querySelector('[data-bw-grad-loss]').textContent=((prediction-5)**2).toFixed(2);root.querySelector('[data-bw-grad-slope]').textContent=g.toFixed(2).replace('-','−');root.querySelector('[data-bw-grad-next]').textContent=next.toFixed(2);root.querySelector('[data-bw-grad-newloss]').textContent=((2*next-5)**2).toFixed(2);};slider.addEventListener('input',update);update();}
  function initOptimizer(root){
    const slider=root.querySelector('[data-bw-lr-slider]');
    const update=()=>{
      const lr=Number(slider.value),next=1+12*lr,loss=(2*next-5)**2;
      root.querySelector('[data-bw-lr-out]').textContent=lr.toFixed(3);
      root.querySelector('[data-bw-lr-next]').textContent=next.toFixed(2);
      root.querySelector('[data-bw-lr-loss]').textContent=loss.toFixed(2);
      const comparison=Math.abs(loss-9)<1e-9?'与原损失 9 相等':loss>9?'比原损失 9 更大':'比原损失 9 更小';
      root.querySelector('[data-bw-lr-note]').textContent='新权重 1−'+lr.toFixed(3)+'×(−12)='+next.toFixed(2)+'；新损失 (2×'+next.toFixed(2)+'−5)²='+loss.toFixed(2)+'，'+comparison+'。本例 η=0.125 时到达 w=2.5 的最低点；继续增大步幅可能跨过它。';
    };
    slider.addEventListener('input',update);update();
  }
  function initAdam(root){const steps=[{g:'+2',m:'1',v:'2',detail:'第 1 步：m₁=0.5×0+0.5×2=1；v₁=0.5×0+0.5×2²=2。'},{g:'0',m:'0.5',v:'1',detail:'第 2 步：方向记录 m₂=0.5×1+0.5×0=0.5；平方大小记录 v₂=0.5×2+0.5×0²=1。'},{g:'−2',m:'−0.75',v:'2.5',detail:'第 3 步：方向记录 m₃=0.5×0.5+0.5×(−2)=−0.75；平方大小记录 v₃=0.5×1+0.5×(−2)²=2.5。'}];const buttons=[...root.querySelectorAll('[data-bw-adam-step]')],rows=[...root.querySelectorAll('[data-bw-adam-row]')];const showStep=index=>{const step=steps[index];buttons.forEach((button,i)=>button.setAttribute('aria-pressed',String(i===index)));rows.forEach((row,i)=>row.classList.toggle('is-current',i===index));root.querySelector('[data-bw-adam-gradient]').textContent=step.g;root.querySelector('[data-bw-adam-m]').textContent=step.m;root.querySelector('[data-bw-adam-v]').textContent=step.v;root.querySelector('[data-bw-adam-detail]').textContent=step.detail;};buttons.forEach((button,index)=>button.addEventListener('click',()=>showStep(index)));}
  function initGradientLedger(root){
    let w=1,grad=null,graph=null,records=[];
    const showNumber=n=>n===null?'None':n.toFixed(3).replace('-','−');
    function paint(message,action){
      root.querySelector('[data-bw-ledger-w]').textContent=showNumber(w);
      root.querySelector('[data-bw-ledger-grad]').textContent=showNumber(grad);
      root.querySelector('[data-bw-ledger-loss]').textContent=graph?showNumber(graph.loss):'尚未计算';
      root.querySelector('[data-bw-ledger-graph]').textContent=graph?'用 w='+showNumber(graph.w)+' 计算；'+(graph.used?'已反向，需重新前向才能再反向':'本次计算图可反向'):'先做前向';
      root.querySelector('[data-bw-ledger-status]').textContent=message;
      if(action){records.push([action,showNumber(w),showNumber(grad),graph?showNumber(graph.loss):'—']);records=records.slice(-6);}
      root.querySelector('[data-bw-ledger-log]').innerHTML=records.map(row=>'<tr>'+row.map((value,i)=>(i?'<td>':'<th scope="row">')+esc(value)+(i?'</td>':'</th>')).join('')+'</tr>').join('');
    }
    root.querySelectorAll('[data-bw-ledger-action]').forEach(button=>button.addEventListener('click',()=>{
      const action=button.dataset.bwLedgerAction;
      if(action==='forward'){const error=2*w-5;graph={w,loss:error**2,gradient:4*error,used:false};paint('前向得到预测 '+showNumber(2*w)+'、损失 '+showNumber(graph.loss)+'；权重和已存梯度都没有改变。','前向');}
      if(action==='backward'){
        if(!graph){paint('尚无损失和计算图，请先做前向。参数和梯度没有变化。','反向未执行');return;}
        if(graph.used){paint('本例同一份 loss 已反向过，所需中间值已释放。请重新前向再反向；不是再点一次就自动覆盖或累加。','反向未执行');return;}
        const before=grad;grad=(grad??0)+graph.gradient;graph.used=true;
        paint('在上次前向 w='+showNumber(graph.w)+' 处求得梯度 '+showNumber(graph.gradient)+'，加到原有的 '+showNumber(before)+' 上，.grad 现在为 '+showNumber(grad)+'。权重仍是 '+showNumber(w)+'。'+(before===null?'None 表示无旧梯度，本次直接存入。':'这就是跨次反向的梯度累加。'),'反向');
      }
      if(action==='clear'){grad=null;paint('清除 .grad 后为 None；权重、上次损失及计算图可否反向的状态都不受影响。','清梯度');}
      if(action==='step'){
        if(grad===null){paint('当前 .grad 为 None，普通 SGD 跳过该参数，权重没有变化。请先计算梯度。','更新跳过');return;}
        const old=w;w-=0.05*grad;paint('SGD：'+showNumber(old)+'−0.05×('+showNumber(grad)+')='+showNumber(w)+'。.grad 仍保留，旧 loss 也不会自动重算；再次更新会继续使用这个梯度。','更新');
      }
      if(action==='reset'){w=1;grad=null;graph=null;records=[];paint('已恢复 w=1、.grad=None。先预测每个操作会改变哪一项，再点击验证。');}
    }));
  }
  function initImage(root){const buttons=root.querySelectorAll('[data-bw-pixel]');buttons.forEach((button,index)=>button.addEventListener('click',()=>{buttons.forEach(item=>item.setAttribute('aria-pressed',String(item===button)));const values=button.dataset.bwPixel.split(',').map(Number);root.querySelector('[data-bw-pixel-position]').textContent='第 '+(Math.floor(index/2)+1)+' 行，第 '+(index%2+1)+' 列';root.querySelector('[data-bw-pixel-rgb]').textContent=values.join(', ');root.querySelector('[data-bw-pixel-float]').textContent=values.map(v=>(v/255).toFixed(2)).join(', ');}));}
  function initTasks(root){const copy={classify:['分类答案：有汽车','只回答整张图片里有没有汽车，不指出它在哪里。'],detect:['检测答案：汽车在矩形框内','在类别之外，还给出每辆汽车的位置；框不是像素级轮廓。'],segment:['分割答案：这些像素属于汽车','逐像素给区域标记；不同分割任务对多个同类物体的区分方式也不同。']};root.querySelectorAll('[data-bw-task]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-bw-task]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));const scene=root.querySelector('.bw-task-demo'),[title,text]=copy[button.dataset.bwTask];scene.dataset.mode=button.dataset.bwTask;root.querySelector('[data-bw-task-title]').textContent=title;root.querySelector('[data-bw-task-copy]').textContent=text;}));}
  const convInput=[1,2,3,4,5,6,7,8,9],convKernel=[1,0,-1,1,0,-1,1,0,-1];
  function initConv(root){const a=root.querySelector('[data-bw-input-grid]'),b=root.querySelector('[data-bw-kernel-grid]'),count=root.querySelector('[data-bw-conv-count]'),sum=root.querySelector('[data-bw-conv-sum]'),line=root.querySelector('[data-bw-conv-line]');a.innerHTML=convInput.map((v,i)=>'<span data-bw-a="'+i+'">'+v+'</span>').join('');b.innerHTML=convKernel.map((v,i)=>'<span data-bw-b="'+i+'">'+v+'</span>').join('');let step=0,total=0;function update(){a.querySelectorAll('span').forEach((cell,i)=>cell.classList.toggle('is-active',i===step-1&&step>0));b.querySelectorAll('span').forEach((cell,i)=>cell.classList.toggle('is-active',i===step-1&&step>0));count.textContent=step+' / 9';sum.textContent=String(total);line.textContent=step?('第 '+step+' 项：'+convInput[step-1]+' × ('+convKernel[step-1]+') = '+convInput[step-1]*convKernel[step-1]+'；累计和 = '+total):'按下“逐项计算”查看每次乘法与累加。';root.querySelector('[data-bw-conv-next]').disabled=step>=9;}root.querySelector('[data-bw-conv-next]').addEventListener('click',()=>{if(step<9){total+=convInput[step]*convKernel[step];step++;update();}});root.querySelector('[data-bw-conv-reset]').addEventListener('click',()=>{step=0;total=0;update();});update();}
  function initFlip(root){const scene=root.querySelector('[data-bw-flip-scene]'),button=root.querySelector('[data-bw-flip-toggle]');button.addEventListener('click',()=>{const flipped=scene.dataset.flipped!=='true';scene.dataset.flipped=String(flipped);const transform='translate(360 0) scale(-1 1)';['[data-bw-flip-car]','[data-bw-flip-box]'].forEach(selector=>{const target=scene.querySelector(selector);if(flipped)target.setAttribute('transform',transform);else target.removeAttribute('transform');});root.querySelector('[data-bw-flip-x]').textContent=flipped?'0.80':'0.20';button.textContent=flipped?'恢复原图':'水平翻转';});}
  const metricRows=[{label:'框 A · 分数 0.95 · 命中目标 1',score:0.95,tp:true},{label:'框 B · 分数 0.82 · 命中目标 2',score:0.82,tp:true},{label:'框 C · 分数 0.61 · 背景误报',score:0.61,tp:false},{label:'框 D · 分数 0.34 · 命中目标 3',score:0.34,tp:true}];
  function initMetrics(root){const slider=root.querySelector('[data-bw-threshold-slider]'),out=root.querySelector('[data-bw-threshold-out]');const levels=[0.7,0.5,0.3];const update=()=>{const threshold=levels[Number(slider.value)],kept=metricRows.filter(row=>row.score>=threshold),tp=kept.filter(row=>row.tp).length,fp=kept.length-tp,fn=3-tp,precision=tp+fp?tp/(tp+fp):0,recall=tp/3,f1=precision+recall?2*precision*recall/(precision+recall):0;out.value=threshold.toFixed(2);out.textContent=threshold.toFixed(2);root.querySelector('[data-bw-ledger]').innerHTML=metricRows.map(row=>'<div class="'+(row.score>=threshold?(row.tp?'is-tp':'is-fp'):'is-hidden')+'"><span>'+(row.score>=threshold?(row.tp?'✓ TP':'× FP'):'— 未保留')+'</span><strong>'+row.label+'</strong></div>').join('')+'<p>本次：TP='+tp+'，FP='+fp+'，FN='+fn+'</p>';root.querySelector('[data-bw-precision]').textContent=(precision*100).toFixed(1)+'%';root.querySelector('[data-bw-recall]').textContent=(recall*100).toFixed(1)+'%';root.querySelector('[data-bw-f1]').textContent=(f1*100).toFixed(1)+'%';};slider.addEventListener('input',update);update();}
  function initRegularization(root){const button=root.querySelector('[data-bw-reg-toggle]');let trained=false;button.addEventListener('click',()=>{trained=!trained;root.querySelector('[data-bw-reg-train]').textContent=trained?'2%':'10%';root.querySelector('[data-bw-reg-val]').textContent=trained?'25%':'12%';root.querySelector('[data-bw-reg-copy]').textContent=trained?'训练错误继续下降、验证错误上升，是过拟合风险信号；应检查数据划分并考虑早停或其他方法。':'当前：两边都表现不错，继续观察验证集变化。';button.textContent=trained?'恢复较早轮次':'多训练一些轮次';});const explanations=['第 1 轮：验证准确率 78%，刷新最佳记录，未提升计数归零。','第 2 轮：验证准确率升到 84%，成为新的最佳结果，计数归零。','第 3 轮：验证准确率升到 86%，保存为当前最佳 checkpoint。','第 4 轮：准确率降到 84%，没有超过最佳值；patience 计数为 1，还观察一轮。','第 5 轮：准确率降到 82%，连续两次没有刷新最佳值；停止训练并恢复第 3 轮 checkpoint。'];const steps=[...root.querySelectorAll('[data-bw-early-step]')],rows=[...root.querySelectorAll('[data-bw-early-row]')];const show=index=>{steps.forEach((item,i)=>item.setAttribute('aria-pressed',String(i===index)));rows.forEach((item,i)=>item.classList.toggle('is-current',i===index));root.querySelector('[data-bw-early-detail]').textContent=explanations[index];};steps.forEach((item,index)=>item.addEventListener('click',()=>show(index)));}
  function initPooling(root){const outputs={max:['4','max(1, 4, 3, 2)'],avg:['2.5','(1 + 4 + 3 + 2) ÷ 4']};root.querySelectorAll('[data-bw-pool]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-bw-pool]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));const [value,calc]=outputs[button.dataset.bwPool];root.querySelector('[data-bw-pool-out]').textContent=value;root.querySelector('[data-bw-pool-calc]').textContent=calc;}));}
  function initIoU(root){const slider=root.querySelector('[data-bw-iou-slider]');const update=()=>{const intersection=Number(slider.value),union=200-intersection;root.querySelector('[data-bw-iou-intersection]').textContent=String(intersection);root.querySelector('[data-bw-iou-union]').textContent=String(union);root.querySelector('[data-bw-iou-value]').textContent=(intersection/union).toFixed(3);};slider.addEventListener('input',update);update();}
  function initDataQuality(root){const frameHost=root.querySelector('[data-bw-frame-groups]'),copy=root.querySelector('[data-bw-split-copy]');const labels=['train','val','train','val','val','train','val','train'];function update(mode){root.querySelectorAll('[data-bw-split]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.bwSplit===mode)));frameHost.dataset.mode=mode;frameHost.innerHTML=Array.from({length:8},(_,i)=>'<span class="frame-'+(mode==='random'?labels[i]:(i<4?'train':'val'))+'" title="拍摄序列 '+(i<4?'A':'B')+' 的第 '+(i%4+1)+' 帧"><small>'+(i<4?'序列 A':'序列 B')+'</small><b>帧 '+(i%4+1)+'</b><em>'+(mode==='random'?labels[i]:(i<4?'train':'val'))+'</em></span>').join('');copy.textContent=mode==='random'?'随机拆分会让相邻帧同时出现在训练与验证中，检查结果不够独立。':'按来源分组后，序列 A 全部用于训练，序列 B 全部用于验证；评估更能反映新拍摄场景。';}root.querySelectorAll('[data-bw-split]').forEach(button=>button.addEventListener('click',()=>update(button.dataset.bwSplit)));update('random');}
  function initQuaternion(root){const slider=root.querySelector('[data-bw-q-slider]'),line=root.querySelector('[data-bw-q-vector]'),point=root.querySelector('[data-bw-q-point]');const update=()=>{const angle=Number(slider.value),rad=angle*Math.PI/180,w=Math.cos(rad/2),z=Math.sin(rad/2),x=Math.cos(rad),y=Math.sin(rad),px=120+70*x,py=100-70*y;root.querySelector('[data-bw-q-angle]').textContent=angle+'°';root.querySelector('[data-bw-q-components]').textContent='q=('+w.toFixed(3)+', 0, 0, '+z.toFixed(3)+')';root.querySelector('[data-bw-q-result]').textContent='('+x.toFixed(3)+', '+y.toFixed(3)+', 0)';line.setAttribute('d','M120 100 L'+px.toFixed(1)+' '+py.toFixed(1));point.setAttribute('cx',px.toFixed(1));point.setAttribute('cy',py.toFixed(1));};slider.addEventListener('input',update);update();}
  function initYoloAugment(root){const scene=root.querySelector('[data-bw-mosaic]'),button=root.querySelector('[data-bw-mosaic-toggle]');button.addEventListener('click',()=>{const mosaic=scene.dataset.mode!=='mosaic';scene.dataset.mode=mosaic?'mosaic':'single';button.textContent=mosaic?'关闭 Mosaic 拼接':'开启 Mosaic 拼接';root.querySelector('[data-bw-mosaic-copy]').textContent=mosaic?'四张来源图拼到一张画布；每个框都要随对应图像缩放、裁切和平移。':'当前是一张原图；标注框围住原图里的目标。';});}
  function initTrainYolo(root){const copy={python:['python：启动 Python 程序的解释器','先确认当前终端使用的是已安装项目依赖的 Python 环境。'],script:['train.py：训练脚本文件','它会读取参数、数据配置和权重文件，然后启动训练循环。'],img:['--img 640：输入尺寸设置','指定训练使用的图像边长示例；较大输入包含更多像素，显存和计算开销也会增加。'],batch:['--batch 16：每批样本数','每次取 16 张图片计算一次损失并更新；可用 batch 受可用显存影响。'],epochs:['--epochs 100：完整遍历次数','示例中计划完整查看训练集 100 次；过多轮次不保证验证效果更好。'],data:['--data data.yaml：数据说明文件','其中写训练/验证图片位置和类别名称，路径应与当前工作目录约定一致。'],weights:['--weights yolov5s.pt：起始参数文件','选择一份预训练参数作为起点；模型结构与类别设置仍要匹配。']};root.querySelectorAll('[data-bw-command]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-bw-command]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));const [title,text]=copy[button.dataset.bwCommand];root.querySelector('[data-bw-command-title]').textContent=title;root.querySelector('[data-bw-command-copy]').textContent=text;}));}
  function initTransfer(root){const button=root.querySelector('[data-bw-transfer-toggle]'),layers=root.querySelector('[data-bw-transfer-state]');button.addEventListener('click',()=>{const frozen=layers.dataset.state==='frozen';layers.dataset.state=frozen?'unfrozen':'frozen';root.querySelector('[data-bw-transfer-copy]').textContent=frozen?'当前：前面层也参与小步微调；通常要观察验证集并谨慎设置学习率。':'当前：前面两层冻结，只更新新的输出头。';button.textContent=frozen?'先冻结前面层':'逐步解冻前面层';});}
  function initArchitecture(root){const copy={backbone:['Backbone：从像素提特征','Conv 逐步计算局部线索，C3 在分支与合并中提炼特征，SPPF 用多次池化扩大可见范围。'],neck:['Neck：合并不同大小的线索','FPN 路径把深层语义传向高分辨率特征；PAN 路径再把位置细节向上汇集，形成多尺度输入。'],head:['Detect Head：产生候选答案','在 P3、P4、P5 等尺度输出框相关数值、物体性分数和类别分数；这些原始输出还要解码与筛选。']};root.querySelectorAll('[data-bw-module]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-bw-module]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));const [title,text]=copy[button.dataset.bwModule];root.querySelector('[data-bw-module-title]').textContent=title;root.querySelector('[data-bw-module-copy]').textContent=text;}));}
  function initAnchors(root){const grid=root.querySelector('[data-bw-anchor-grid]'),status=root.querySelector('[data-bw-anchor-cell]');for(let row=0;row<4;row++)for(let col=0;col<4;col++){const button=document.createElement('button');button.type='button';button.setAttribute('aria-label','第 '+(row+1)+' 行，第 '+(col+1)+' 列网格');button.dataset.row=row;button.dataset.col=col;button.setAttribute('aria-pressed',String(row===1&&col===2));if(row===1&&col===2)button.classList.add('is-target-cell');button.addEventListener('click',()=>{grid.querySelectorAll('button').forEach(cell=>{cell.setAttribute('aria-pressed',String(cell===button));cell.classList.toggle('is-selected',cell===button);});const correct=row===1&&col===2;status.textContent='你选了第 '+(row+1)+' 行、第 '+(col+1)+' 列。'+(correct?'目标中心正好落在这里。':'目标中心实际落在第 2 行、第 3 列。');});grid.appendChild(button);}status.textContent='目标中心落在第 2 行、第 3 列';const templates={small:{width:160,height:120,x:80,y:20,iou:'0.781',label:'模板 A 160×120',detail:'中心对齐时，模板 A 完全落在目标框内：交集 19,200，面积并集 24,576，IoU≈0.781。'},large:{width:320,height:160,x:0,y:0,iou:'0.480',label:'模板 B 320×160',detail:'中心对齐时，目标框完全落在模板 B 内：交集 24,576，面积并集 51,200，IoU≈0.480。'}};root.querySelectorAll('[data-bw-anchor-template]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-bw-anchor-template]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));const item=templates[button.dataset.bwAnchorTemplate];const rect=root.querySelector('[data-bw-anchor-template-rect]');rect.setAttribute('x',item.x);rect.setAttribute('y',item.y);rect.setAttribute('width',item.width);rect.setAttribute('height',item.height);root.querySelector('[data-bw-anchor-template-label]').textContent=item.label;root.querySelector('[data-bw-anchor-iou]').textContent=item.iou;root.querySelector('[data-bw-anchor-match-copy]').textContent=item.detail;}));}
  function initDataset(root){const slider=root.querySelector('[data-bw-dataset-x-slider]');if(!slider)return;const update=()=>{const x=Number(slider.value);root.querySelector('[data-bw-dataset-x-out]').value=x.toFixed(2);root.querySelector('[data-bw-dataset-x-out]').textContent=x.toFixed(2);root.querySelector('[data-bw-dataset-line]').textContent='0 '+x.toFixed(2)+' 0.50 0.20 0.30';root.querySelector('[data-bw-dataset-pixels]').textContent='('+Math.round(x*640)+', 240)；128×144 px';root.querySelector('[data-bw-dataset-box]').setAttribute('x',String(x*320-32));root.querySelector('[data-bw-dataset-center]').setAttribute('cx',String(x*320));};slider.addEventListener('input',update);update();}
  function initParts(root){const copy={box:['框的位置','把预测框和真实框比较。YOLOv5 的具体实现使用 CIoU 相关定位损失，既看重叠，也考虑中心距离和形状比例。'],obj:['物体性','预测这个位置含有目标的程度。常见 YOLOv5 训练实现会用匹配框 IoU 构造软目标；背景候选则按分配规则监督。'],cls:['类别','在需要类别监督的正样本位置，比较类别预测与真实类别。类别标签与“有没有物体”是两个不同问题。']};root.querySelectorAll('[data-bw-loss-part]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-bw-loss-part]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));const [title,text]=copy[button.dataset.bwLossPart];root.querySelector('[data-bw-loss-title]').textContent=title;root.querySelector('[data-bw-loss-copy]').textContent=text;}));}
  function initInference(root){const copy=[['预处理：把图片整理成训练时约定的数字','调整尺寸、颜色通道和数值范围；如果训练时用了补边，推理后要记录补边比例以便还原框。'],['模型输出：每个位置产生一组原始数值','这些数值表示候选框、物体性与类别的分数；它们还不是最后的概率和最终画出的结果。'],['阈值筛选：先去掉明显低分候选','置信度门槛筛掉低分框；门槛调高会少报一些目标，也可能漏掉较难的目标。'],['NMS 与坐标还原：合并重复项、还原到原图','NMS 根据类别与框重叠处理重复候选；最后撤销缩放和补边，映射回原图坐标。']];root.querySelectorAll('[data-bw-inference]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-bw-inference]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));const [title,text]=copy[Number(button.dataset.bwInference)];root.querySelector('[data-bw-inference-title]').textContent=title;root.querySelector('[data-bw-inference-copy]').textContent=text;}));}
  function initDebug(root){const copy=[['第一步：确认输入真的读到了目标','打开原图与标签核对配对、类别编号和框位置；再检查预处理后的图像是否仍清晰可见。'],['第一步：检查非有限值从哪里出现','从输入、模型输出、损失、梯度逐段查看是否出现 NaN/Inf；回退到最小批次，检查标签范围与学习率。'],['第一步：确认类别编号对应表','检查 names 顺序、标签 class id 范围与类别数，再看标注框是否指向正确物体。']];root.querySelectorAll('[data-bw-debug]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-bw-debug]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));const [title,text]=copy[Number(button.dataset.bwDebug)];root.querySelector('[data-bw-debug-title]').textContent=title;root.querySelector('[data-bw-debug-copy]').textContent=text;}));}
  function initTraining(root){
    const batches=root.querySelector('[data-bw-batches]'),counter=root.querySelector('[data-bw-loop-step]'),label=root.querySelector('[data-bw-loop-label]'),button=root.querySelector('[data-bw-loop-next]');
    batches.innerHTML=Array.from({length:4},(_,i)=>'<span data-bw-batch="'+i+'">批次 '+(i+1)+'<small>2 张</small></span>').join('');
    let step=0;
    function update(){
      const completed=Math.floor(step/3),batch=Math.ceil(step/3),phase=(step-1)%3;
      counter.textContent=completed+' / 4 次更新已完成';
      label.textContent=step===0?'尚未取出第一批':step===12?'第 4 批更新完成：本 epoch 已处理 8 张图片':('第 '+batch+' 批：'+['取出 2 张图片和标签；清除旧梯度','前向预测，并计算本批损失','反向求梯度，再 step 更新参数'][phase]);
      batches.querySelectorAll('[data-bw-batch]').forEach((item,i)=>{item.classList.toggle('is-current',step>0&&i===batch-1);item.querySelector('small').textContent=i<completed?'2 张 · 已更新':step>0&&i===batch-1?'2 张 · 处理中':'2 张 · 等待';});
      button.disabled=step===12;
      button.textContent=step===12?'本轮已完成':step%3===0?'取出第 '+(completed+1)+' 批':step%3===1?'前向并计算损失':'反向并更新参数';
    }
    button.addEventListener('click',()=>{if(step<12)step++;update();});
    root.querySelector('[data-bw-loop-reset]').addEventListener('click',()=>{step=0;update();});update();
  }
  function initPoolingCoverage(root){const grid=root.querySelector('[data-bw-pool-coverage-grid]'),result=root.querySelector('[data-bw-pool-results]'),status=root.querySelector('[data-bw-pool-coverage-copy]'),shape=root.querySelector('[data-bw-pool-shape]');if(!grid)return;const strideButtons=[...root.querySelectorAll('[data-bw-pool-stride]')];let stride=1,selected=0,windows=[];function paint(index){selected=index;const item=windows[index];grid.querySelectorAll('[data-bw-pool-cell]').forEach(cell=>cell.classList.toggle('is-window-cell',item.cells.includes(Number(cell.dataset.bwPoolCell))));result.querySelectorAll('button').forEach((button,i)=>button.setAttribute('aria-pressed',String(i===selected)));status.textContent='输出窗口从第 '+(item.y+1)+' 行、第 '+(item.x+1)+' 列开始，读取 '+item.values.join('、')+'，最大值为 '+item.value+'。';}function update(){windows=[];for(let y=0;y<=1;y+=stride)for(let x=0;x<=1;x+=stride){const cells=[y*3+x,y*3+x+1,(y+1)*3+x,(y+1)*3+x+1],values=cells.map(index=>index+1);windows.push({x,y,cells,values,value:Math.max(...values)});}selected=0;result.innerHTML=windows.map((item,index)=>'<button type="button" data-bw-pool-output="'+index+'" aria-pressed="'+String(index===0)+'" aria-label="输出第 '+(item.y+1)+' 行、第 '+(item.x+1)+' 列，数值 '+item.value+'">'+item.value+'</button>').join('');shape.textContent=(stride===1?'2 × 2':'1 × 1');strideButtons.forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.bwPoolStride)===stride)));result.querySelectorAll('[data-bw-pool-output]').forEach((button,index)=>button.addEventListener('click',()=>paint(index)));paint(0);}strideButtons.forEach(button=>button.addEventListener('click',()=>{stride=Number(button.dataset.bwPoolStride);update();}));update();}
  function initHSV(root){const h=root.querySelector('[data-bw-hsv-h]');if(!h)return;const s=root.querySelector('[data-bw-hsv-s]'),v=root.querySelector('[data-bw-hsv-v]'),art=root.querySelector('[data-bw-hsv-art]');const update=()=>{const hue=Number(h.value),sat=Number(s.value),val=Number(v.value);art.style.filter='hue-rotate('+hue+'deg) saturate('+sat+') brightness('+val+')';root.querySelector('[data-bw-hsv-h-out]').textContent=hue+'°';root.querySelector('[data-bw-hsv-s-out]').textContent=sat.toFixed(1)+'×';root.querySelector('[data-bw-hsv-v-out]').textContent=val.toFixed(1)+'×';};[h,s,v].forEach(input=>input.addEventListener('input',update));update();}
  function initDropoutDemo(root){const nodes=[...root.querySelectorAll('[data-bw-dropout-node]')],button=root.querySelector('[data-bw-dropout-next]'),status=root.querySelector('[data-bw-dropout-status]');if(!nodes.length)return;let index=0;const update=()=>{nodes.forEach((node,i)=>node.classList.toggle('is-dropped',i===index));status.textContent='示意：训练时暂时关闭节点 '+String.fromCharCode(65+index)+'，它本步输出为 0。'};button.addEventListener('click',()=>{index=(index+1)%nodes.length;update();});update();}
  function initHardNegative(root){const button=root.querySelector('[data-bw-hard-negative-toggle]'),copy=root.querySelector('[data-bw-hard-negative-copy]');if(!button)return;let shown=false;button.addEventListener('click',()=>{shown=!shown;copy.textContent=shown?'正确标签：背景里没有车辆；这张图是困难负例。':'模型可能把阴影误报成车；数据标签仍应写“没有车辆”。';button.textContent=shown?'再看模型可能怎样误判':'查看正确标签';});}
  function initTrainQuickstart(root){const section=root.querySelector('.bw-yolo-quickstart');if(!section)return;section.dataset.ready='true';}
  function initImageBudget(root){const buttons=[...root.querySelectorAll('[data-bw-image-size]')],bar=root.querySelector('[data-bw-image-budget-bar]'),copy=root.querySelector('[data-bw-image-budget-copy]');if(!buttons.length)return;const base=320*320;buttons.forEach(button=>button.addEventListener('click',()=>{const size=Number(button.dataset.bwImageSize),pixels=size*size,ratio=pixels/base;buttons.forEach(item=>item.setAttribute('aria-pressed',String(item===button)));bar.style.width=(ratio/9*100)+'%';copy.textContent=size+'×'+size+' = '+pixels.toLocaleString('en-US')+' 个像素，约为 320 基准的 '+ratio+' 倍。';}));}
  function initMetricsAndOthers(root){const id=root.dataset.bwRoot;if(id==='regularization')initRegularization(root);if(id==='pooling')initPooling(root);if(id==='iou')initIoU(root);if(id==='metrics')initMetrics(root);if(id==='data-quality')initDataQuality(root);if(id==='quaternion')initQuaternion(root);if(id==='transfer')initTransfer(root);if(id==='architecture')initArchitecture(root);if(id==='anchors')initAnchors(root);if(id==='dataset')initDataset(root);if(id==='yolo-loss')initParts(root);if(id==='yolo-augment')initYoloAugment(root);if(id==='train-yolo')initTrainYolo(root);if(id==='inference')initInference(root);if(id==='debugging')initDebug(root);if(id==='training-loop')initTraining(root);}
  function initialize(){document.querySelectorAll('[data-bw-root]').forEach(root=>{const id=root.dataset.bwRoot;if(id==='tensor')initTensor(root);else if(id==='network')initNetwork(root);else if(id==='gradient')initGradient(root);else if(id==='gradient-diagnostics')initGradientLedger(root);else if(id==='optimizer')initOptimizer(root);else if(id==='optimizer-momentum')initAdam(root);else if(id==='image')initImage(root);else if(id==='tasks')initTasks(root);else if(id==='cnn')initConv(root);else if(id==='augmentation')initFlip(root);initMetricsAndOthers(root);if(id==='pooling')initPoolingCoverage(root);if(id==='augmentation')initHSV(root);if(id==='regularization')initDropoutDemo(root);if(id==='data-quality')initHardNegative(root);if(id==='train-yolo')initTrainQuickstart(root);if(id==='yolo-augment')initImageBudget(root);});}
  window.renderFoundationWorkshop=render;
  window.initializeFoundationWorkshops=initialize;
})();
